-- ====================================================================
-- 10: SETEL ULANG COUNTER audit_log — perbaikan [referensi: audit_log_pkey]
-- ====================================================================
-- Penyebab: audit_log.id memakai BIGINT GENERATED BY DEFAULT AS IDENTITY,
--     seed mengisi id 1..23 manual → identity sequence tidak ikut maju
--     (BY DEFAULT tidak otomatis). Insert pertama dari RPC (fn_create_contract,
--     fn_activate_contract, fn_generate_monthly_invoices, dll) mencoba id=1
--     → duplicate key audit_log_pkey → seluruh transaksi di-rollback.
-- Solusi: setel ulang sequence ke MAX(id) yang sebenarnya. Aman diulang.
-- ====================================================================

DO $$
DECLARE
    v_max BIGINT;
BEGIN
    SELECT COALESCE(MAX(id), 0) INTO v_max FROM public.audit_log;

    IF v_max = 0 THEN
        PERFORM setval(pg_get_serial_sequence('public.audit_log', 'id'), 1, false);
    ELSE
        PERFORM setval(pg_get_serial_sequence('public.audit_log', 'id'), v_max);
    END IF;
END;
$$;

-- ====================================================================
-- VERIFIKASI (jalankan manual, opsional)
-- ====================================================================
-- Sebelum skrip (diagnosa penyebab):
--   SELECT MAX(id) AS id_terisi FROM public.audit_log;  → mis. 23
--   SELECT pg_sequence_last_value('audit_log_id_seq'::regclass); → 1/NULL
--   → perbedaan inilah penyebab pesan "dobel [referensi: audit_log_pkey]".
--
-- Setelah skrip:
--   SELECT nextval(pg_get_serial_sequence('public.audit_log','id'));
--   → harus mengembalikan MAX(id)+1 (mis. 24), bukan 1.
-- ====================================================================
